"""Writes figures/captions.md. Every count is read from saved results (nothing typed in): python -I figures/write_captions.py"""
import sys
sys.path.insert(0, "figures")
import pandas as pd
import numpy as np
from common import P2, P3, P4, P5, P6, TASKS, load

M = load(P2 + "metrics.json"); D = load(P4 + "price_of_recall.json"); X3 = load(P3 + "cascade.json")
g = pd.read_parquet(P2 + "groups.parquet")
oof = pd.read_parquet(P3 + "cascade_oof_rep0.parquet")
n_boot = M["n_boot"]; seeds = M["seeds"]
mt = {t: M["metrics"][f"group_{t}"] for t in TASKS}; mr = {t: M["metrics"][f"random_{t}"] for t in TASKS}
test_txt = ", ".join(f"{t} {mt[t]['n_test']} MOFs in {mt[t]['n_test_groups']} groups" for t in TASKS)
rand_txt = ", ".join(f"{t} {mr[t]['n_test']}" for t in TASKS)
cal = {}
for t in TASKS:
    p = pd.read_parquet(P2 + f"pred_group_{t}_s0.parquet"); cal[t] = (int((p.split == "cal").sum()), p[p.split == "cal"].group_id.nunique())
cal_txt = ", ".join(f"{t} {cal[t][0]} MOFs in {cal[t][1]} groups" for t in TASKS)
nlab, nstab, ngr = len(oof), int(oof.all_stable.sum()), oof.group_id.nunique()
reps, K = len(X3["results"]), X3["K"]
pool = ", ".join(f"{t} {D['real']['phase3_' + t]['n']} MOFs in {D['real']['phase3_' + t]['n_groups']} groups" for t in TASKS)
total_m, total_g = len(g), g.group_id.nunique()
split_txt = (f"Splits: {total_m:,} MOFs (union of the three stability tables) in {total_g:,} proxy groups (connected components over 4-letter CSD refcode family and DOI; "
             f"no MOFid is available in the released data), each group wholly in one of train / validation / calibration / test (60/20/20 by MOF count, split seed 0).")

RFd, NNd = pd.read_parquet(P5 + "split_ranges_rf.parquet"), pd.read_parquet(P5 + "split_ranges_nn.parquet")
nrf, nnn = RFd.split_seed.nunique(), NNd.split_seed.nunique()
_t = pd.concat([RFd, NNd]).groupby("stage").n_test.agg(["min", "max"])
tr_txt = ", ".join(f"{t} {int(_t.loc[t, 'min'])}-{int(_t.loc[t, 'max'])}" for t in TASKS)
gap_txt = ", ".join(f"{t} {int((RFd[(RFd.stage == t) & (RFd['mode'] == 'random')].set_index('split_seed')['auc_stable'] > RFd[(RFd.stage == t) & (RFd['mode'] == 'group')].set_index('split_seed')['auc_stable']).sum())}/{nrf}" for t in TASKS)
FS_ = load(P5 + "family_shift.json"); fs_k, fs_r = FS_["K"], FS_["R"]
fs_test = " / ".join(f"{np.mean([r['n_test'] for r in FS_['results'][t]]):.0f}" for t in TASKS)
fs_med = ", ".join(f"{t} {np.median([r['recall_0.1'] for r in FS_['results'][t]]):.3f}" for t in TASKS)

JG = pd.read_parquet(P6 + "joint_cascade_group_pvalues.parquet")
j_pos_rep = int(JG.groupby("rep").all_stable.sum().iloc[0]); j_reps = JG.rep.nunique(); j_lab = int(JG.groupby("rep").size().iloc[0]); j_pos_eval = int(JG.all_stable.sum())
j_groups = int(g[g.name.isin(JG[JG.all_stable & (JG.rep == 0)].name)].group_id.nunique())
j_gmin, j_gmax = int(JG.n_cal_groups.min()), int(JG.n_cal_groups.max())

txt = f"""# Draft figure captions

Generated by `figures/write_captions.py` from saved results (`data/processed/phase2..4/`); regenerate with `python -I figures/write_captions.py`.
Files: `figN_*.pdf` is the double-column version (17.5 cm wide), `figN_*_1col.pdf` the single-column version (8.5 cm wide); same content, panels stacked in the single-column version.
Common to Figs. 2-5: {split_txt} Figs. 1 and 6 use many splits / clusterings instead of split seed 0 (see their captions). Groups are proxies, so near-duplicate MOFs in different groups may remain across splits. Labels are the released labels.
Stage names: thermal = decomposition temperature >= 350 °C, solvent = solvent-removal (activation) stable, water = water stable (class 2 or 3); 'truly stable' = stable by these released labels.

## Figure 1 (`fig1_group_vs_random`)
**Group-aware splitting lowers the measured performance of the stability models; the size of the drop varies from split to split.** Test performance when the same model is trained on a MOF-level random split (grey squares) or on a group-aware split (orange circles) of the same MOFs, shown as the **median with the 2.5-97.5% range over splits** (not a single split). (a) AUC for the 'truly stable' call; (b) accuracy of the stable / not-stable call; (c) thermal mean absolute error (\u00b0C). Filled markers: random forest, {nrf} splits; open markers: released networks (fixed early-stopping restore; thermal and solvent) and released forest (water), {nnn} splits. Split seed s gives one random-group split and one MOF-level random split over the union of the three tables (60/20/20 by MOF count; {total_g:,} proxy groups, refcode family + DOI; no MOFid), so the two modes are paired; test parts hold {tr_txt} MOFs depending on the split. Share of paired random-forest splits in which the group-aware AUC is lower: {gap_txt}. The ranges are across splits of one dataset, not confidence intervals for a new dataset; the spread for the open markers rests on only {nnn} splits. Labels are the released labels; groups are proxies, so near-duplicates may remain across splits.

## Figure 2 (`fig2_recall_vs_target`)
**Realised recall of the per-stage conformal threshold.** Realised recall on the group-aware test set against the target recall 1 − α, for the thermal (a), solvent (b) and water (c) stages; grey squares: Phase 2 models (released hyperparameters), orange circles: Phase 3 models (tree-model candidates chosen by group cross-validation on the training groups only); dashed line: target. Thresholds are the k-th smallest calibration-positive score, k = floor(α (n+1)), from the group-aware calibration set ({cal_txt}) and applied to the test sets ({test_txt}). Shaded bands are 95% percentile bootstrap intervals ({n_boot} resamples) over test groups with the threshold held fixed; they show test-set sampling noise only, not the variability of the calibration draw. Each point is one calibration draw (split seed 0), so single points can lie below the diagonal even though the guarantee is for the average over draws.

## Figure 3 (`fig3_kept_vs_recall`)
**Fraction of MOFs kept at each target recall.** Share of all group-aware test MOFs that pass the conformal threshold of each stage (thermal a, solvent b, water c) against the target recall; same models, thresholds and test sets as Fig. 2 (test sets: {test_txt}). Dotted line: a filter without information (kept = recall). Shaded bands: 95% percentile bootstrap intervals ({n_boot} resamples) over test groups, threshold fixed. Lower is better at equal realised recall, but the two model sets have different realised recalls at the same target, so compare them at equal realised recall (see Fig. 2).

## Figure 4 (`fig4_cascade`)
**Stacked thermal, solvent and water filters (cascade) on the MOFs with all three labels.** (a) Recall on the {nstab} MOFs that are stable at all three stages, against the target recall 1 − α. (b) Fraction of the {nlab} MOFs carrying all three labels ({ngr} proxy groups) that pass all three filters. Orange circles: Phase 3 models with the union bound (each stage calibrated at α/3); grey squares: Phase 2 models with the union bound; green triangles: Phase 3 models without the union bound (each stage at α). Scores and thresholds are out-of-fold: groups are split into K = {K} folds, three stages are trained and calibrated on the other folds' groups, and the procedure is repeated for {reps} fold assignments (small dots in (a)); markers are means over the repetitions. Error bars are 95% Clopper-Pearson intervals for the rounded mean count of passes out of {nstab} and do **not** account for the repetitions, which re-use the same MOFs and are not independent. With only {nstab} positives the intervals are wide: the data are consistent with the guarantee but cannot confirm it. Phase 3 configurations were chosen on the training groups of the single split, which gives a small selection leak into these folds. The {nstab} all-stable MOFs are those with thermal >= 350 \u00b0C, solvent label +1 and water class 2 or 3 (a different cut-off gives 3-49). The union bound is **not proved** for this population: each stage's guarantee covers that stage's own stable MOFs, and the all-stable MOFs score lower than the other stage-stable MOFs for thermal and water.

## Figure 5 (`fig5_price_of_recall`)
**The price of recall: fraction of MOFs kept against discriminative power (AUC).** For each stage (thermal a, solvent b, water c) and target recall 0.80 / 0.90 / 0.95 (colours), the fraction of all MOFs that must be kept so that this fraction of the truly stable MOFs is kept, with the threshold known exactly (isolating discrimination from calibration noise). Lines: analytic binormal model at the stage's prevalence. Small squares: **simulated** scores (negatives N(0,1), positives N(d,1)) on each stage's real labels and group ids, one dataset per AUC value, plotted at the sample AUC; they are not measured. Open squares and filled circles: **real** Phase 2 and Phase 3 stage models. Real and synthetic points use the pooled group-aware calibration and test MOFs ({pool}), seed-0 models. Bars are 95% percentile bootstrap intervals ({n_boot} resamples) over groups (both axes for the real models). Simulated scores are independent of group, which is optimistic, and real score distributions need not be binormal.

## Figure 6 (`fig6_family_shift`)
**Under a shift to new MOF families the per-stage conformal rule can miss its recall target.** Realised test recall against the target recall 1 \u2212 \u03b1 for the thermal (a), solvent (b) and water (c) stages. MOFs of each stage are embedded without labels (z-scored released features, PCA 20) and clustered (k-means, K = {fs_k}); whole clusters go to test (about 20% of MOFs), other whole clusters to calibration (about 20%), the rest to training of a random forest (pre-specified, 300 trees). Orange: the split-conformal threshold is calibrated on the calibration clusters, which differ from the test clusters (cross-cluster; test sets {fs_test} MOFs per repetition on average for thermal / solvent / water). Grey: control, calibrated on a random half of the test clusters and evaluated on the other half (calibrate-within; exchangeable by construction). Lines: median over {fs_r} repetitions (new k-means seed and cluster order each time); bands: 2.5-97.5% range over repetitions, which for {fs_r} repetitions is close to the minimum-maximum. The repetitions re-use the same MOFs and are not independent, and the result depends on the clustering recipe (one recipe, K and the embedding not varied). Median cross-cluster recall at target 0.90: {fs_med}. Means over repetitions (used in `notes/phase5.md`) are lower than the medians for the cross-cluster case because the distribution over repetitions is left-skewed. Dashed line: target.

## Figure 7 (`fig7_joint_cascade`)
**Joint cascade rule calibrated on the all-three-stable MOFs: realised recall against the guarantee, and the price in kept MOFs.** The joint score is the minimum of the three rank-normalised stage scores; a MOF is kept when its cross-conformal (CV+ / jackknife+ style) p-value exceeds \u03b1. Calibration positives: the {j_pos_rep} MOFs stable at all three stages among the {j_lab} MOFs labelled in all three tables, which lie in {j_groups} groups. (a) Realised recall on these {j_pos_rep} MOFs against \u03b1, for calibration with the {j_groups} groups as units (orange; each group's score is the minimum over its positives) and with the {j_pos_rep} MOFs as units (grey), with the guaranteed recall 1 \u2212 2\u03b1 (dashed line, valid under exchangeability of the calibration units and a symmetric fitting procedure; borrowed from the jackknife+ / CV+ theorem, not re-proved). The blue marker and dotted line show the **highest certifiable target with {j_groups} units, 1 \u2212 2/15 = 0.867** (\u03b1 = 1/15; a smaller \u03b1 gives a trivial rule that keeps everything); with {j_pos_rep} units it would be 0.889. (b) Fraction of the {j_lab} labelled MOFs kept by the group-level joint rule, the MOF-level joint rule and the union bound (\u03b1/3 per stage, each stage calibrated on its own stable MOFs). Evaluation: nested group cross-fitting with random-forest stage models, test MOFs excluded from every model and from calibration, {j_reps} repetitions (outer seeds 0-{j_reps - 1}) of the same {j_lab} MOFs; the calibration pool in each fold holds {j_gmin}-{j_gmax} groups. Points in (a) pool the {j_reps} repetitions ({j_pos_eval} positive evaluations); the **intervals are Clopper-Pearson 95% intervals that treat these {j_pos_eval} evaluations as independent, so they are optimistic** (they re-use {j_pos_rep} MOFs in {j_groups} groups). With so few positives the data have little power to contradict the guarantee. Recall is measured on MOFs that happen to carry all three labels, not on the screening population.
"""
open("figures/captions.md", "w").write(txt)
print(txt)
